// SPDX-License-Identifier: MPL-2.0
//
// G09-R2 — real configured-provider image/video generation and candidate
// adoption.
//
// This is the production service behind the frozen `generation.*` BridgeV6
// actions. It reuses the accepted generation's existing authorities:
//
//  * `MediaGenerationJobStore` for durable provider jobs (owner
//    `.document(projectID)`, idempotency key + exact payload/owner replay);
//  * `CreativeAssetStore` for the canonical generated bytes;
//  * `G09MediaProjectHost` for the ONE media-project CAS/intent transaction
//    that adopts a candidate;
//  * `ModelConfigurationStore`, `ModelSelectionPreferences`,
//    `RunCredentialResolver` / `SecretGatewayRegistry` for configuration and
//    credentials (bytes never leave the provider call point).
//
// No second project/job database exists. No provider is called during catalog
// listing. No secret is stored in a job payload or returned to the App.
import Foundation
import FloeCore
import FloePersistence
import FloeProviders
import FloeAndroidWorkbench
#if canImport(FoundationNetworking)
import FoundationNetworking
#endif

// MARK: - Injectable environment / transport seam

public struct G09R2GenerationEnvironment: Sendable {
    public let root: RuntimeStorageRoot
    public let database: DatabaseManager
    public let configuration: ModelConfigurationStore

    public init(root: RuntimeStorageRoot, database: DatabaseManager,
                configuration: ModelConfigurationStore) {
        self.root = root
        self.database = database
        self.configuration = configuration
    }

    public var artifactRoot: URL { root.artifactStoreURL }
}

public struct G09R2DownloadReceipt: Sendable {
    public var fileURL: URL
    public var byteCount: Int64
    public var sha256: String

    public init(fileURL: URL, byteCount: Int64, sha256: String) {
        self.fileURL = fileURL
        self.byteCount = byteCount
        self.sha256 = sha256
    }
}

/// Provider/network seams are injected so focused tests can run with
/// synthetic adapters and a synthetic download; production uses the real
/// factories, the registered credential gateway and streamed HTTPS download.
public struct G09R2GenerationPlatform: Sendable {
    public var imageAdapter: @Sendable (ProviderProfile) -> (any ImageProviderAdapter)?
    public var videoAdapter: @Sendable (ProviderProfile) -> (any VideoProviderAdapter)?
    public var credentials: @Sendable (ProviderProfile) async throws -> ProviderCredentials
    public var download: @Sendable (URL, URL, Int64) async throws -> G09R2DownloadReceipt

    public init(
        imageAdapter: @escaping @Sendable (ProviderProfile) -> (any ImageProviderAdapter)? = {
            ImageProviderAdapterFactory().adapter(for: $0)
        },
        videoAdapter: @escaping @Sendable (ProviderProfile) -> (any VideoProviderAdapter)? = {
            VideoProviderAdapterFactory().adapter(for: $0)
        },
        credentials: @escaping @Sendable (ProviderProfile) async throws -> ProviderCredentials = {
            try await RunCredentialResolver().credentials(for: $0)
        },
        download: @escaping @Sendable (URL, URL, Int64) async throws -> G09R2DownloadReceipt = {
            try await G09R2GenerationDownload.stream(from: $0, to: $1, maximumBytes: $2)
        }
    ) {
        self.imageAdapter = imageAdapter
        self.videoAdapter = videoAdapter
        self.credentials = credentials
        self.download = download
    }
}

// MARK: - Durable job payload

/// Exact request identity persisted BEFORE the provider call. The session
/// token is never persisted; `sessionProof` is an opaque digest used only to
/// prove the submitting editor session, never as authority for a later one.
internal struct G09R2GenerationJobPayload: Codable, Sendable, Equatable {
    var schemaVersion: Int
    var kind: G09R2GenerationKind
    var projectID: UUID
    var ownerKind: String
    var writeLayer: String
    var originKind: String?
    var originOwnerID: UUID?
    var epoch: UInt64
    var sessionProof: String
    var routeID: String
    var providerID: UUID
    var modelID: UUID
    var remoteModelID: String
    var prompt: String
    var size: String?
    var count: Int
    var sourceAssetID: UUID?
    var referenceAssetIDs: [UUID]
    var durationSeconds: Double?
    var aspectRatio: String?
    var resolution: String?
    var idempotencyKey: String
    var opID: String
    var expectedRevision: Int64

    init(kind: G09R2GenerationKind, context: G09R2ProjectContextDTO,
         epoch: UInt64, route: G09R2ModelRouteDTO,
         request: G09R2ImageGenerationRequestDTO) {
        self.schemaVersion = 1
        self.kind = kind
        self.projectID = context.projectID
        self.ownerKind = "document"
        self.writeLayer = Self.writeLayer(context.storage)
        self.originKind = context.origin?.kind.rawValue
        self.originOwnerID = context.origin?.ownerID
        self.epoch = epoch
        self.sessionProof = G09CreativeAssetHost.sessionDigest(context.sessionToken)
        self.routeID = route.routeID
        self.providerID = UUID(uuidString: route.providerID) ?? UUID()
        self.modelID = UUID(uuidString: route.routeID) ?? UUID()
        self.remoteModelID = route.remoteModelID
        self.prompt = request.prompt
        self.size = request.size
        self.count = request.count
        self.sourceAssetID = request.sourceAssetID
        self.referenceAssetIDs = request.referenceAssetIDs
        self.durationSeconds = nil
        self.aspectRatio = nil
        self.resolution = nil
        self.idempotencyKey = request.idempotencyKey
        self.opID = ""
        self.expectedRevision = 0
    }

    init(kind: G09R2GenerationKind, context: G09R2ProjectContextDTO,
         epoch: UInt64, route: G09R2ModelRouteDTO,
         request: G09R2VideoGenerationRequestDTO) {
        self.schemaVersion = 1
        self.kind = kind
        self.projectID = context.projectID
        self.ownerKind = "document"
        self.writeLayer = Self.writeLayer(context.storage)
        self.originKind = context.origin?.kind.rawValue
        self.originOwnerID = context.origin?.ownerID
        self.epoch = epoch
        self.sessionProof = G09CreativeAssetHost.sessionDigest(context.sessionToken)
        self.routeID = route.routeID
        self.providerID = UUID(uuidString: route.providerID) ?? UUID()
        self.modelID = UUID(uuidString: route.routeID) ?? UUID()
        self.remoteModelID = route.remoteModelID
        self.prompt = request.prompt
        self.size = nil
        self.count = 1
        self.sourceAssetID = request.sourceAssetID
        self.referenceAssetIDs = request.referenceAssetIDs
        self.durationSeconds = request.durationSeconds
        self.aspectRatio = request.aspectRatio
        self.resolution = request.resolution
        self.idempotencyKey = request.idempotencyKey
        self.opID = ""
        self.expectedRevision = 0
    }

    private static func writeLayer(_ storage: G09StorageLayerDTO) -> String {
        switch storage.kind {
        case .appOwned: "appOwned"
        case .workspace: "workspace:\(storage.workspaceID?.uuidString.lowercased() ?? "")"
        }
    }

    func withOperation(_ opID: String, expectedRevision: Int64)
        -> G09R2GenerationJobPayload {
        var copy = self
        copy.opID = opID
        copy.expectedRevision = expectedRevision
        return copy
    }

    /// Exact operation identity, excluding the original local CAS
    /// precondition. Used only after the durable job lookup by idempotency
    /// key; it never re-authorizes a provider submission by itself.
    func replayIdentityEquals(_ other: G09R2GenerationJobPayload) -> Bool {
        var left = self
        var right = other
        left.expectedRevision = 0
        right.expectedRevision = 0
        return left == right
    }

    var namespacedIdempotencyKey: String {
        "g09r2.\(projectID.uuidString.lowercased()).\(idempotencyKey)"
    }

    var fingerprint: String {
        let data = (try? G09CreativeWire.encoder().encode(self)) ?? Data()
        return FloeDigest.sha256Hex(data)
    }
}

// MARK: - Service

public final class G09R2GenerationService: @unchecked Sendable {
    public static let shared = G09R2GenerationService()

    /// Bounded live provider/IO workers for one process. Waiting provider jobs
    /// stay durable in the database and do not occupy a worker slot.
    public static let maximumLiveWorkers = 8
    /// A preparing job with no live worker and no staged result is classified
    /// unknown after this delay; it is never automatically resubmitted.
    public static let stalePreparingSeconds: TimeInterval = 180
    /// Bounded refresh wait so the creative bridge is never held for minutes.
    public static let refreshWaitSeconds: TimeInterval = 2.5
    /// Download retries before the result URL is treated as unavailable.
    public static let maximumDownloadRetries = 5

    internal struct Worker {
        let token: String
        let epoch: UInt64
        let jobID: String
        let kind: G09R2GenerationKind
        var cancelRequested: Bool
        var task: Task<Void, Never>?
    }

    private let lock = NSLock()
    private var workers: [String: Worker] = [:]
    private var stoppingEpoch: UInt64?
    private var inflightKeys: Set<String> = []
    private var finalizing: Set<String> = []
    private var candidateStores: [String: G09R2CandidateStore] = [:]

    internal let platform: G09R2GenerationPlatform
    internal let environmentProvider: @Sendable (UInt64) async
        -> G09R2GenerationEnvironment?

    public convenience init() {
        self.init(platform: G09R2GenerationPlatform(), environmentProvider: {
            epoch in
            guard let cluster = await AndroidRuntimeBootstrap.creativeCluster(
                epoch: epoch) else { return nil }
            return G09R2GenerationEnvironment(
                root: cluster.identity.root,
                database: cluster.database,
                configuration: cluster.modelConfigurationStore)
        })
    }

    public init(
        platform: G09R2GenerationPlatform,
        environmentProvider: @escaping @Sendable (UInt64) async
            -> G09R2GenerationEnvironment?
    ) {
        self.platform = platform
        self.environmentProvider = environmentProvider
    }

    // MARK: - Worker table / root drain

    internal func startWorker(
        epoch: UInt64, jobID: String, kind: G09R2GenerationKind,
        body: @escaping @Sendable (String) async -> Void
    ) -> Bool {
        let token = UUID().uuidString.lowercased()
        lock.lock()
        guard stoppingEpoch != epoch else {
            lock.unlock()
            return false
        }
        guard workers.count < Self.maximumLiveWorkers else {
            lock.unlock()
            return false
        }
        workers[token] = Worker(
            token: token, epoch: epoch, jobID: jobID, kind: kind,
            cancelRequested: false, task: nil)
        lock.unlock()
        let task = Task.detached { [weak self] in
            await body(token)
            self?.finishWorker(token)
        }
        lock.lock()
        if var worker = workers[token] {
            worker.task = task
            if worker.cancelRequested { task.cancel() }
            workers[token] = worker
        }
        lock.unlock()
        return true
    }

    internal func finishWorker(_ token: String) {
        lock.lock()
        workers.removeValue(forKey: token)
        lock.unlock()
    }

    /// Registers a short local operation (final candidate commit / download
    /// finalisation) as REAL owned work so a concurrent Root stop can cancel
    /// its task and waits for actual settlement. The body runs in a child task
    /// registered with the worker table; a cancel request reaches it and its
    /// streamed HTTP/download/commit checks observe `Task.isCancelled`.
    internal func withLocalWork(
        epoch: UInt64, kind: G09R2GenerationKind, id: String,
        _ body: @escaping @Sendable () async -> Void
    ) async {
        guard let token = beginLocalWork(epoch: epoch, kind: kind, id: id) else {
            return
        }
        let task = Task { await body() }
        attachWorkerTask(token: token, task: task)
        await task.value
        finishWorker(token)
    }

    private func attachWorkerTask(token: String, task: Task<Void, Never>) {
        lock.lock()
        if var worker = workers[token] {
            worker.task = task
            if worker.cancelRequested { task.cancel() }
            workers[token] = worker
        }
        lock.unlock()
    }

    internal func beginLocalWork(
        epoch: UInt64, kind: G09R2GenerationKind, id: String
    ) -> String? {
        let token = UUID().uuidString.lowercased()
        lock.lock(); defer { lock.unlock() }
        guard stoppingEpoch != epoch,
              workers.count < Self.maximumLiveWorkers else { return nil }
        workers[token] = Worker(
            token: token, epoch: epoch, jobID: id, kind: kind,
            cancelRequested: false, task: nil)
        return token
    }

    internal func isWorkerCancelled(_ token: String) -> Bool {
        lock.lock(); defer { lock.unlock() }
        return workers[token]?.cancelRequested ?? true
    }

    internal func hasActiveWorker(jobID: String) -> Bool {
        lock.lock(); defer { lock.unlock() }
        return workers.values.contains { $0.jobID == jobID }
    }

    /// Whether any live worker belongs to one epoch. Test hosts drain their
    /// owned epochs before closing the database so no background worker can
    /// touch a closed GRDB connection.
    internal func hasActiveWorker(epoch: UInt64) -> Bool {
        lock.lock(); defer { lock.unlock() }
        return workers.values.contains { $0.epoch == epoch }
    }

    /// Phase-1 root stop: refuse new workers for this generation, request
    /// cancellation of the exact owned tasks, and report TRUE only after every
    /// worker actually settled. A cancel flag alone is never drain proof.
    public func requestRootStop(epoch: UInt64) -> Bool {
        lock.lock()
        stoppingEpoch = epoch
        var tasks: [Task<Void, Never>] = []
        for token in Array(workers.keys) {
            guard var worker = workers[token], worker.epoch == epoch else {
                continue
            }
            worker.cancelRequested = true
            if let task = worker.task { tasks.append(task) }
            workers[token] = worker
        }
        let pending = workers.values.contains { $0.epoch == epoch }
        lock.unlock()
        for task in tasks { task.cancel() }
        // A worker may have settled, but its App foreground lease is a REAL
        // separate ownership still held by the notification service. Root
        // stop cannot claim drained until the host releases that exact lease
        // after it stopped the service; this is the foreground-ownership ack.
        let foreground = G09R2ForegroundCoordinator.shared.leaseCount(epoch: epoch)
        return !pending && foreground == 0
    }

    /// Requests cancellation of the exact captured native job. This is used by
    /// the App notification Cancel/timeout path through the host-only C ABI;
    /// it does not accept a session token, a UI token or a client root. The
    /// worker remains the terminal owner: provider billing cancellation is
    /// only claimed when the configured adapter actually supports it.
    @discardableResult
    internal func requestCancel(jobID: String, epoch: UInt64) -> Bool {
        let normalized = jobID.lowercased()
        lock.lock()
        var tasks: [Task<Void, Never>] = []
        var matched = false
        for token in Array(workers.keys) {
            guard var worker = workers[token], worker.epoch == epoch,
                  worker.jobID == normalized else { continue }
            matched = true
            worker.cancelRequested = true
            if let task = worker.task { tasks.append(task) }
            workers[token] = worker
        }
        lock.unlock()
        for task in tasks { task.cancel() }
        return matched
    }

    internal func foregroundLeaseCount(epoch: UInt64) -> Int {
        G09R2ForegroundCoordinator.shared.leaseCount(epoch: epoch)
    }

    /// Host-only bounded pump step for an exact leased video job. The App
    /// `dataSync` service calls this while the UI is backgrounded so a real
    /// provider task keeps progressing without a UI session token. It reuses
    /// the durable payload/task/backoff and the SAME `runVideoPoll` worker;
    /// no second job store and no client root/session are accepted.
    public func foregroundPoll(epoch: UInt64, jobID: String) async -> Bool {
        guard epoch > 0, let uuid = UUID(uuidString: jobID) else { return false }
        guard let cluster = await BridgeV5.service.r2BoundCluster(),
              cluster.epoch == epoch else { return false }
        guard !isRootStopping(epoch: epoch),
              !(await BridgeV5.service.r2IsRootStopping(epoch: epoch)),
              !G09R2MediaRenderHostMailbox.shared.isRootStopping(epoch: epoch)
        else { return false }
        guard let env = await environmentProvider(epoch),
              env.root.path == cluster.root.path else { return false }
        let store = jobStore(env)
        guard let owned = try? await store.ownedJob(id: uuid),
              !owned.job.state.isTerminal,
              owned.job.mediaKind == .video,
              owned.owner.kind == .document else { return false }
        guard let payload = try? decodePayload(owned.job),
              payload.epoch == epoch,
              payload.kind == .video,
              payload.projectID == owned.owner.id else { return false }
        let jobKey = uuid.uuidString.lowercased()
        if hasActiveWorker(jobID: jobKey) { return true }
        if let next = owned.job.nextPollAt, next > Date(),
           owned.job.state != .downloading,
           owned.job.state != .completed {
            return true
        }
        guard owned.job.providerTaskID != nil
                || owned.job.state == .downloading
                || owned.job.state == .completed else { return false }
        guard G09R2ForegroundCoordinator.shared.hasLease(
            jobID: jobKey, epoch: epoch) else { return false }
        return startWorker(
            epoch: epoch, jobID: jobKey, kind: .video,
            body: { [weak self] token in
                guard let self else { return }
                await self.runVideoPoll(
                    token: token, service: BridgeV5.service, epoch: epoch,
                    jobID: uuid, payload: payload)
            })
    }

    public func isRootStopping(epoch: UInt64) -> Bool {
        lock.lock(); defer { lock.unlock() }
        return stoppingEpoch == epoch
    }

    public func pendingWorkerCount(epoch: UInt64) -> Int {
        lock.lock(); defer { lock.unlock() }
        return workers.values.filter { $0.epoch == epoch }.count
    }

    internal func beginInflight(_ key: String) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard !inflightKeys.contains(key) else { return false }
        inflightKeys.insert(key)
        return true
    }

    internal func endInflight(_ key: String) {
        lock.lock(); inflightKeys.remove(key); lock.unlock()
    }

    internal func beginFinalize(_ jobID: String) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard !finalizing.contains(jobID) else { return false }
        finalizing.insert(jobID)
        return true
    }

    internal func endFinalize(_ jobID: String) {
        lock.lock(); finalizing.remove(jobID); lock.unlock()
    }

    internal func candidateStore(root: URL) -> G09R2CandidateStore {
        let key = root.standardizedFileURL.path
        lock.lock(); defer { lock.unlock() }
        if let existing = candidateStores[key] { return existing }
        let store = G09R2CandidateStore(artifactRoot: root)
        candidateStores[key] = store
        return store
    }

    // MARK: - Shared validation

    internal func requireCluster(
        _ service: G09CreativeDomainService, epoch: UInt64
    ) async throws -> G09R2BoundCluster {
        guard let cluster = await service.r2BoundCluster(),
              cluster.epoch == epoch else {
            throw G09CreativeError.staleGeneration
        }
        return cluster
    }

    internal func requireEnvironment(
        _ cluster: G09R2BoundCluster, epoch: UInt64
    ) async throws -> G09R2GenerationEnvironment {
        guard let env = await environmentProvider(epoch) else {
            throw G09CreativeError.staleGeneration
        }
        guard env.root.path == cluster.root.path else {
            throw G09CreativeError.staleGeneration
        }
        return env
    }

    internal func requireNoRootStop(
        _ service: G09CreativeDomainService, epoch: UInt64
    ) async throws {
        guard !isRootStopping(epoch: epoch),
              !G09R2MediaRenderHostMailbox.shared.isRootStopping(epoch: epoch),
              !(await service.r2IsRootStopping(epoch: epoch)) else {
            throw G09R2Error(.renderCancelled, detail: "rootStopping")
        }
    }

    internal func requireContext(_ context: G09R2ProjectContextDTO) throws {
        guard G09CreativeWire.validSessionToken(context.sessionToken) else {
            throw G09CreativeError.invalidPayload("invalidSessionToken")
        }
        _ = try context.storage.validatedWorkspaceID()
    }

    internal func requireMediaSession(
        _ service: G09CreativeDomainService,
        context: G09R2ProjectContextDTO
    ) async throws {
        try await service.r2RequireMediaSession(
            projectID: context.projectID, token: context.sessionToken)
    }

    internal func loadProject(
        _ cluster: G09R2BoundCluster, context: G09R2ProjectContextDTO
    ) async throws -> G09MediaProjectHost.Loaded {
        do {
            return try await cluster.media.load(
                id: context.projectID, requested: context.storage,
                origin: context.origin)
        } catch let typed as G09CreativeError {
            throw typed
        } catch {
            throw G09CreativeError.map(error)
        }
    }

    internal func requireProject(
        _ cluster: G09R2BoundCluster, context: G09R2ProjectContextDTO,
        expectedRevision: Int64? = nil
    ) async throws -> G09MediaProjectHost.Loaded {
        let loaded = try await loadProject(cluster, context: context)
        guard loaded.writable else { throw G09CreativeError.provenanceMismatch }
        if let expectedRevision, loaded.project.revision != expectedRevision {
            throw G09CreativeError.revisionConflict
        }
        return loaded
    }

    internal func jobStore(_ env: G09R2GenerationEnvironment)
        -> MediaGenerationJobStore {
        MediaGenerationJobStore(database: env.database)
    }

    internal func assetStore(_ env: G09R2GenerationEnvironment)
        -> CreativeAssetStore {
        CreativeAssetStore(
            database: env.database, reachabilityGuard: nil,
            deferPhysicalReclamation: true)
    }

    // MARK: - Catalog

    public func models(service: G09CreativeDomainService, epoch: UInt64)
        async throws -> G09R2ModelCatalogDTO {
        let cluster = try await requireCluster(service, epoch: epoch)
        try await requireNoRootStop(service, epoch: epoch)
        let env = try await requireEnvironment(cluster, epoch: epoch)
        let providers = try await env.configuration.providers()
        let models = try await env.configuration.models()
        let preferences = try? await env.configuration.preferences()
        return G09R2GenerationCatalog.build(
            models: models, providers: providers, preferences: preferences,
            imageAdapter: { (profile: ProviderProfile) in
                self.platform.imageAdapter(profile)
            },
            videoAdapter: { (profile: ProviderProfile) in
                self.platform.videoAdapter(profile)
            })
    }

    /// Resolves the exact configured route again at request time. A route that
    /// disappeared or lost its adapter is `modelUnavailable`; no fallback to a
    /// different paid route is ever chosen.
    internal func resolveRoute(
        env: G09R2GenerationEnvironment, kind: G09R2GenerationKind,
        routeID: String, operation: RemoteImageOperation? = nil
    ) async throws -> (G09R2ModelRouteDTO, ProviderProfile, ModelProfile) {
        let providers = try await env.configuration.providers()
        let models = try await env.configuration.models()
        let preferences = try? await env.configuration.preferences()
        let catalog = G09R2GenerationCatalog.build(
            models: models, providers: providers, preferences: preferences,
            imageAdapter: { (profile: ProviderProfile) in
                self.platform.imageAdapter(profile)
            },
            videoAdapter: { (profile: ProviderProfile) in
                self.platform.videoAdapter(profile)
            })
        let routes = kind == .image ? catalog.image : catalog.video
        guard let route = routes.first(where: {
            $0.routeID == routeID.lowercased()
        }) else {
            throw G09R2Error(.modelUnavailable, detail: "routeRemoved")
        }
        guard route.enabled else {
            throw G09R2Error(.modelUnavailable, detail: "routeDisabled")
        }
        guard route.available else {
            throw G09R2Error(
                .modelUnavailable,
                detail: route.unavailableReason ?? "routeUnavailable")
        }
        guard let modelUUID = UUID(uuidString: route.routeID),
              let providerUUID = UUID(uuidString: route.providerID),
              let model = models.first(where: { $0.id == modelUUID }),
              let provider = providers.first(where: { $0.id == providerUUID }),
              provider.isEnabled, model.isEnabled else {
            throw G09R2Error(.modelUnavailable, detail: "routeRemoved")
        }
        guard model.supportsImageGenerationSurface == (kind == .image)
                || model.supportsVideoGenerationSurface == (kind == .video) else {
            throw G09R2Error(.modelUnavailable, detail: "surfaceChanged")
        }
        if kind == .image, let operation,
           let adapter = platform.imageAdapter(provider),
           !adapter.supports(operation, for: provider) {
            throw G09R2Error(.modelUnavailable, detail: "operationUnsupported")
        }
        return (route, provider, model)
    }

    // MARK: - Handles / status mapping

    internal func imageState(_ job: MediaGenerationJob) -> G09R2ImageRequestState {
        switch job.state {
        case .preparing:
            if job.lastError == "outcomeUnknown" { return .outcomeUnknown }
            if job.lastError == "interrupted" { return .interrupted }
            return .submitted
        case .submitted:
            return .submitted
        case .running:
            return .running
        case .completed, .downloading:
            return .running
        case .ready:
            return .completed
        case .failed:
            return .failed
        case .cancelled:
            return .dismissed
        case .expired:
            return job.lastError == "outcomeUnknown" ? .outcomeUnknown : .interrupted
        }
    }

    internal func mediaJobState(_ job: MediaGenerationJob)
        -> G09R2MediaJobState {
        switch job.state {
        case .preparing:
            if job.lastError == "outcomeUnknown" { return .outcomeUnknown }
            if job.lastError == "interrupted" { return .interrupted }
            return .submitted
        case .submitted: return .submitted
        case .running: return .running
        case .completed: return .running
        case .downloading: return .downloading
        case .ready: return .completed
        case .failed: return .failed
        case .cancelled: return .cancelled
        case .expired:
            return job.lastError == "outcomeUnknown" ? .outcomeUnknown : .interrupted
        }
    }

    internal func boundedErrorCode(_ raw: String?) -> String? {
        guard let raw, !raw.isEmpty else { return nil }
        let allowed = raw.unicodeScalars.allSatisfy {
            CharacterSet.alphanumerics.contains($0) || $0 == "." || $0 == "_"
                || $0 == "-"
        }
        guard allowed, raw.utf8.count <= 64 else { return "generationFailed" }
        return raw
    }

    internal func isRetryable(_ code: String?) -> Bool {
        guard let code else { return false }
        switch code {
        case "generationUnavailable", "modelUnavailable", "providerTimeout",
             "rendererUnavailable", "insufficientStorage", "staleGeneration",
             "staleSession", "storageUnavailable", "acceptedRootNotLive",
             "candidateCommitPending", "downloadCommitPending":
            return true
        default:
            return false
        }
    }

    internal func jobStatus(
        _ owned: OwnedMediaGenerationJob, candidate: G09R2CandidateRecord?
    ) -> G09R2JobStatusDTO {
        let job = owned.job
        let state = mediaJobState(job)
        return G09R2JobStatusDTO(
            jobID: job.id.uuidString.lowercased(),
            projectID: owned.owner.id,
            state: state,
            updatedAt: job.updatedAt,
            progressHint: nil,
            resultAvailable: job.state == .ready && job.localAssetID != nil
                && candidate != nil,
            providerTaskReferencePresent: job.providerTaskID != nil,
            lastErrorCode: boundedErrorCode(job.lastError),
            retryable: isRetryable(boundedErrorCode(job.lastError)),
            canCancel: !job.state.isTerminal && job.providerTaskID != nil)
    }

    internal func imageStatusDTO(
        _ job: MediaGenerationJob, projectID: UUID,
        candidate: G09R2CandidateRecord?, dismissed: Bool
    ) -> G09R2ImageRequestStatusDTO {
        G09R2ImageRequestStatusDTO(
            requestID: job.id.uuidString.lowercased(),
            projectID: projectID,
            state: dismissed ? .dismissed : imageState(job),
            submittedAt: job.createdAt,
            updatedAt: job.updatedAt,
            candidate: candidate?.dto,
            errorCode: dismissed ? nil : boundedErrorCode(job.lastError),
            retryable: !dismissed && isRetryable(boundedErrorCode(job.lastError)))
    }

    // MARK: - Models/handles

    internal func decodePayload(_ job: MediaGenerationJob) throws
        -> G09R2GenerationJobPayload {
        do {
            return try G09CreativeWire.decoder().decode(
                G09R2GenerationJobPayload.self, from: job.requestJSON)
        } catch {
            throw G09CreativeError.corruptProject
        }
    }

    internal func verifyReplay(
        _ owned: OwnedMediaGenerationJob, payload: G09R2GenerationJobPayload
    ) throws -> G09R2GenerationJobPayload {
        guard owned.owner == .document(payload.projectID),
              owned.job.providerID == payload.providerID,
              owned.job.modelID == payload.modelID else {
            throw G09CreativeError.invalidPayload("intentMismatch")
        }
        let existing = try decodePayload(owned.job)
        // `expectedRevision` is the local CAS precondition captured at the
        // original explicit action. It is not part of the provider request
        // identity: a replay after the project revision advanced (for example
        // a prior adoption) must still attach to the SAME durable terminal
        // job instead of paying for a second provider task. Every other field
        // (opID, idempotency key, prompt, route, ownership) must match
        // exactly; the store's opID/key collision refusal is unchanged.
        guard existing.replayIdentityEquals(payload) else {
            throw G09CreativeError.invalidPayload("intentMismatch")
        }
        return existing
    }
}
